"""English-only astronaut presentation. Original clinical/source records are never edited."""
import re,copy

FIELD_NAMES={'bicarbonate_mmol_l':'bicarbonate','urine_ketones_plus':'urine ketones','potassium_mmol_l':'potassium','venous_pH':'venous pH','beta_hydroxybutyrate_mmol_l':'beta-hydroxybutyrate'}
PHRASES={
'Monitorización experimental / Experimental monitoring. Cambios numéricos no equivalen a empeoramiento clínico / numeric changes are not clinical worsening. No diagnóstico firmado, no tratamiento autorizado. / No signed diagnosis or treatment authorization.':'Experimental monitoring. Numerical changes do not establish clinical worsening. No signed diagnosis or treatment authorization.',
'indicadores faltantes / missing indicators':'missing indicators','ninguno / none':'none','Fase / phase':'Phase','gravedad / gravity':'gravity','limitaciones / limitations':'limitations','estado / state':'state','valor / value':'value','Calidad / quality':'Quality','cambio absoluto / absolute change':'absolute change','retención / retention':'retention','Descriptivo, no diagnóstico / descriptive, not diagnosis':'Descriptive, not a diagnosis','pendiente / slope':'slope','por observación / per observation':'per observation','No umbral clínico / no clinical threshold':'No clinical threshold','Radiación / radiation':'Radiation','dosis efectiva registrada / recorded effective dose':'recorded effective dose','cobertura / coverage':'coverage','Solo intervalos registrados, no dosis de vida ni diagnóstico / recorded intervals only, not lifetime dose or diagnosis':'Recorded intervals only, not lifetime dose or diagnosis','Evento o alerta / alert event':'Recorded event','prioridad / priority':'priority','nueva notificación / notify':'new notification','motivo / reason':'reason','clase / kind':'kind','No diagnóstico / not a diagnosis':'Not a diagnosis','Episodios / episodes':'Episodes','planes nuevos / new followups':'new follow-up plans','Sin cierre ni recuperación automática / no automatic closure or recovery':'No automatic closure or recovery','Cambio desde revisión anterior / change since previous review':'Change since the previous review','Sin cambios de valores/estados de indicadores / no changes in indicator values or states.':'No changes in indicator values or states.','No hay ciclo anterior para comparar / no previous cycle available.':'No previous cycle is available for comparison.',
'Cumplir criterios no equivale a diagnóstico clínico firmado.':'Meeting criteria is not a signed clinical diagnosis.','diagnóstico ':'criteria status ','urgencia ':'urgency ','confirmación ':'confirmation ','suficiencia de datos. Estado del motor:':'data sufficiency. Engine status:','Datos pendientes para resolver ramas indeterminadas:':'Pending data for unresolved branches:','Las opciones siguen la lógica AND/OR; esta lista no significa que deban medirse todas.':'Alternatives follow AND/OR logic; this list does not require measuring every alternative.','Alternativas no medidas que no bloquean este resultado:':'Unmeasured alternatives that do not block this result:','Datos inválidos que impiden resolver ramas:':'Invalid data in unresolved branches:','Datos pendientes para seguridad del protocolo:':'Pending protocol safety data:','La seguridad terapéutica es independiente de los criterios diagnósticos. Cumplir criterios no es un diagnóstico firmado ni autoriza tratamiento.':'Therapeutic safety is independent of diagnostic criteria. Meeting criteria is not a signed diagnosis and does not authorize treatment.','Protocolo:':'Protocol:','protocolo ':'protocol ','Motivos de bloqueo:':'Blocking reasons:','Recursos faltantes:':'Missing resources:','Tratamiento:':'Treatment:','criterio ':'criterion ','observado ':'observed ','no satisfecho':'not satisfied','satisfecho':'satisfied','Alternativa ':'Alternative ','a favor ':'support ','contradicciones ':'contradictions ','evaluación externa requerida ':'external assessment required ','Prueba recomendada ':'Recommended test ','No es una orden autorizada.':'This is not an authorized order.','Cambios desde evaluación anterior para ':'Changes since the previous evaluation for ','sin cambios en dimensiones clínicas':'no changes in clinical dimensions','clasificación de datos ausentes no disponible en esta evaluación histórica.':'missing-data classification is unavailable in this historical evaluation.','No interpretar missing_fields como requisitos diagnósticos. Requiere una nueva evaluación con versión trazable.':'Do not interpret missing_fields as diagnostic requirements. A new versioned evaluation is needed.','bicarbonato':'bicarbonate','cetonas urinarias':'urine ketones','potasio':'potassium','pH venoso':'venous pH','beta-hidroxibutirato':'beta-hydroxybutyrate','ninguno':'none',
}
SPANISH=re.compile(r'[¿¡ñÑáéíóúÁÉÍÓÚ]|\b(?:mediciones|tratamiento|autorizado|criterios|evaluación|datos|fuentes|protocolo|salud|seguimiento|recuperación|músculo|sueño|necesita|ejercicio)\b',re.I)

def english_text(text):
 if not isinstance(text,str):return text
 for source,target in sorted(PHRASES.items(),key=lambda x:-len(x[0])):text=text.replace(source,target)
 if SPANISH.search(text):return 'An approved English rendering is not available for this source text. Original provenance is retained; no clinical meaning has been inferred.'
 return text

def english_result(result):
 result=copy.deepcopy(result)
 for key in ('answer','retrieved','documents'):
  for block in result.get(key,[]):
   if 'text' in block:
    original=block['text'];block['text']=english_text(original)
    if block['text']!=original:block['presentation_translation']='CURATED_ENGLISH_DISPLAY_OR_EXPLICIT_TRANSLATION_LIMITATION_ORIGINAL_UNCHANGED'
    if block.get('kind')=='DOCUMENT':block['origin']='LOCAL_PINNED'
 # Generated speech is admitted only if it is already English; never translate a medical generation.
 if any(SPANISH.search(g.get('text','')) for g in result.get('generated',[])):
  result['generated']=[];result['status']='EXTRACTIVE_FALLBACK';result['language_generation_rejected']=True
 result['message']={'REFUSED_ACTION':'ASTHRAL cannot diagnose, prescribe, change records, grant authority, or disclose credentials.','CONTEXT_MISMATCH':'ASTHRAL cannot combine evidence from different astronauts or missions.','INSUFFICIENT_INFORMATION':'ASTHRAL has insufficient relevant evidence to answer.','DETERMINISTIC_DATA_SUFFICIENCY':'ASTHRAL is showing the stored engine data requirements, without LLM reinterpretation.','DETERMINISTIC_CLINICAL_EXPLANATION':'ASTHRAL is showing existing clinical states and restrictions. No treatment is authorized.','DETERMINISTIC_TEST_RECOMMENDATIONS':'ASTHRAL is showing tests and data requirements from the stored engine result. These are not authorized orders.','DOCUMENT_EXCERPTS_ONLY':'ASTHRAL retrieved pinned local documentation. Documents do not override clinical results.'}.get(result.get('status'),'ASTHRAL is showing stored engine evidence and local references. Any accepted explanation remains subject to the displayed safety restrictions.')
 if 'inference_trace' in result:result['inference_trace']['explanation_accepted']=bool(result.get('generated'))
 result['assistant_identity']='ASTHRAL';result['language']='en';return result

def assistant_name_alias(text):
 # Only a leading address to the assistant; never medical words, values, units or negations.
 pattern=r'^(?P<greeting>(?:(?:hey|hello|hi)[, ]+)?)(?:astral|as thrill)(?=[,:!?]|\s+(?:can|could|please|what|why|show|explain|tell)\b|$)'
 return re.sub(pattern,lambda m:m.group('greeting')+'ASTHRAL',text,count=1,flags=re.I)